from __future__ import annotations

import collections
import json
import subprocess
import sys
from pathlib import Path

from .common import atomic_json, read_jsonl, refuse_test_path, sha256_file
from .data import closure_from_expected


def scheduler_config(step: int, lora_name: str, adapter_dir: Path, ecfg: dict, paths: dict,
                     protocol_path: Path, endpoints: list[str], out_root: Path) -> dict:
    bundle = refuse_test_path(Path(paths["val_bundle"]))
    return {
        "_how_to_read": "Generated by nautil_rlvr for periodic validation of the RLVR adapter.",
        "run_name": f"rlvr_val_step{step:05d}", "output_root": str(out_root),
        "protocol": str(protocol_path),
        "prompt_variants": {"default": {"impl": "default", "system_prompt": str(paths["system_prompt"])}},
        "datasets": {"validation_v1": {"bundle": str(bundle), "bundle_sha256": sha256_file(bundle),
                                       "split": "validation"}},
        "backends": {"gpu": {"type": "vllm_completions", "tokenizer": ecfg.get("tokenizer") or str(paths["base_model"]),
                             "endpoints": [{"label": f"ep{i}", "url": url,
                                            "target_concurrency": int(ecfg.get("concurrency", 32))}
                                           for i, url in enumerate(endpoints)]}},
        "conditions": [{"name": f"rlvr_step{step:05d}", "backend": "gpu", "model": lora_name,
                        "adapter_path": str(adapter_dir), "prompt_variant": "default",
                        "fetch_policy": {"name": "own_choice"}, "evidence_transform": {"name": "full"},
                        "datasets": ["validation_v1"], "samples": int(ecfg.get("samples", 1))}],
        "retry": {"max_attempts": 3, "backoff_seconds": 15},
        "status_interval_seconds": 120, "metrics_interval_seconds": 10,
        "sync": {"enabled": False}, "test_lock": {"frozen_protocol": None}}


def run_scheduler(cfg_path: Path, ecfg: dict, log_path: Path) -> int:
    cmd = [ecfg.get("python") or sys.executable, "-m", "nautil_scheduler", "run", "--config", str(cfg_path)]
    if ecfg.get("selftest_mock"):
        cmd.append("--selftest-mock")
    import os
    env = dict(os.environ)
    env.pop("PYTHONPATH", None)
    env["HF_HUB_OFFLINE"] = "1"
    for k in [k for k in env if k == "API_KEY" or k.endswith("_API_KEY") or "_API_KEY_" in k]:
        env.pop(k)
    with Path(log_path).open("w") as log:
        proc = subprocess.run(cmd, cwd=str(ecfg["scheduler_scripts_dir"]), stdout=log, env=env,
                              stderr=subprocess.STDOUT, timeout=float(ecfg.get("timeout_seconds", 7200)))
    return proc.returncode


def val_labels(refs_path: Path) -> dict[str, str]:
    refs_path = refuse_test_path(Path(refs_path))
    return {r["case_id"]: closure_from_expected(r["expected_closure"]) for r in read_jsonl(refs_path)}


def summarize(records: list[dict], labels: dict[str, str]) -> dict:
    by_src = collections.defaultdict(lambda: {"n": 0, "correct": 0})
    n = len(records)
    out = collections.Counter()
    right = {"closed": [0, 0], "not_closed": [0, 0]}
    for r in records:
        marker = r.get("conclusion_marker")
        decision = "closed" if marker == "CASE CLOSED" else "not_closed" if marker == "CASE NOT CLOSED" else None
        label = labels[r["case_id"]]
        ok = decision == label
        right[label][0] += ok
        right[label][1] += 1
        s = by_src[r["source"]]
        s["n"] += 1
        s["correct"] += ok
        out["finals"] += r.get("status") == "final"
        out["no_marker"] += decision is None
        out["valid_citations"] += r.get("final_citations_all_disclosed") is True
        out["tool_error_turns"] += sum(bool(t.get("call_errors")) or
                                       (isinstance(t.get("tool_return"), dict) and "error" in t["tool_return"])
                                       for t in r.get("turns", []))
        out["turns"] += r.get("assistant_turns", 0)
        out["fetch_rounds"] += r.get("fetch_rounds", 0)
        out["turn_limit"] += r.get("status") == "turn_limit"
    rate = lambda a, b: a / b if b else None
    closed_acc = rate(*right["closed"])
    notc_acc = rate(*right["not_closed"])
    return {"records": n, "final_rate": rate(out["finals"], n), "no_marker_rate": rate(out["no_marker"], n),
            "valid_citation_rate": rate(out["valid_citations"], n),
            "tool_error_turns_per_case": rate(out["tool_error_turns"], n),
            "turns_per_case": rate(out["turns"], n), "fetch_rounds_per_case": rate(out["fetch_rounds"], n),
            "turn_limit_rate": rate(out["turn_limit"], n),
            "closure_acc_ref_closed": closed_acc, "closure_acc_ref_not_closed": notc_acc,
            "closure_balanced_acc": (closed_acc + notc_acc) / 2 if closed_acc is not None and notc_acc is not None else None,
            "closure_acc_by_source": {k: rate(v["correct"], v["n"]) for k, v in sorted(by_src.items())},
            "counts": {"ref_closed": right["closed"][1], "ref_not_closed": right["not_closed"][1]}}


def collect(out_root: Path, cond_name: str) -> list[dict]:
    d = Path(out_root) / cond_name / "validation_v1"
    return [json.loads(p.read_text()) for p in sorted(d.glob("*__s*.json"))
            if not p.name.endswith(".failed.json")]


def llm_closure_scores(records: list[dict], paths: dict, judge, rcfg, subset=None) -> dict:
    from .reward import render_closure_request, model_closed, scale
    cases = {c["case_id"]: c for c in read_jsonl(refuse_test_path(Path(paths["val_bundle"])))}
    refs = {r["case_id"]: r for r in read_jsonl(refuse_test_path(Path(paths["val_judge_refs"])))}
    futs = []
    for rec in records:
        if subset and rec["case_id"] not in subset:
            continue
        req = render_closure_request(rec, cases[rec["case_id"]], refs[rec["case_id"]], rcfg)
        if req is None:
            continue
        closed = model_closed(rec)
        futs.append((rec, closed, judge.submit("closure", req[0], 1, closed)))
    raw_c, raw_g, scaled, by_label, failed = [], [], [], collections.defaultdict(list), 0
    sc = rcfg.scaling
    for rec, closed, fut in futs:
        out = fut.result()
        if "error" in out:
            failed += 1
            continue
        c = out["conclusion"]["score"]
        raw_c.append(c)
        if closed:
            v = scale(c, sc["closure_conclusion_closed"])
        else:
            g = out["gap"]["score"]
            raw_g.append(g)
            v = scale(c, sc["closure_conclusion_not_closed"]) + scale(g, sc["closure_gap_not_closed"])
        scaled.append(v)
        by_label[refs[rec["case_id"]]["closure"]].append(c)
    m = lambda xs: sum(xs) / len(xs) if xs else None
    return {"scored": len(raw_c), "failed": failed, "no_marker_skipped": len(records) - len(futs),
            "conclusion_raw_mean": m(raw_c), "gap_raw_mean": m(raw_g), "closure_llm_scaled_mean": m(scaled),
            **{f"conclusion_raw_mean_ref_{k}": m(v) for k, v in by_label.items()},
            "raw_conclusion_scores": raw_c, "raw_gap_scores": raw_g,
            "judge_health": {k: v for k, v in judge.cumulative().items() if not isinstance(v, dict)}}


def run_eval(step: int, lora_name: str, adapter_dir: Path, ecfg: dict, paths: dict,
             protocol_path: Path, endpoints: list[str], run_dir: Path) -> tuple[dict, list[dict]]:
    out_root = Path(run_dir) / "eval" / f"step_{step:05d}"
    out_root.mkdir(parents=True, exist_ok=True)
    cfg = scheduler_config(step, lora_name, adapter_dir, ecfg, paths, protocol_path, endpoints,
                           out_root / "scheduler_out")
    cfg_path = out_root / "scheduler_config.json"
    atomic_json(cfg_path, cfg)
    code = run_scheduler(cfg_path, ecfg, out_root / "scheduler.log")
    records = collect(out_root / "scheduler_out", cfg["conditions"][0]["name"])
    summary = summarize(records, val_labels(Path(paths["val_refs"]))) if records else {"records": 0}
    summary.update({"step": step, "lora_name": lora_name, "scheduler_exit_code": code})
    atomic_json(out_root / "summary.json", summary)
    return summary, records
